test('book command installs closed and guarded admission refuses missing aggregate triggers',async()=>{
 assert.equal(await value(client,"SELECT count(*)::int AS value FROM pg_roles WHERE rolname='crest_booking_owner' AND NOT(rolcanlogin OR rolinherit OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls) AND rolconfig IS NULL"),1);
 assert.equal(await value(client,"SELECT count(*)::int AS value FROM pg_auth_members WHERE roleid='crest_booking_owner'::regrole OR member='crest_booking_owner'::regrole"),0);
 await client.query('BEGIN');await client.query('ALTER TABLE crest.jobs DISABLE TRIGGER booking_graph');await assert.rejects(client.query(modules.at(-1)),e=>e.code==='42501'&&e.message==='CREST_BOOKING_GUARDS_REQUIRED');await client.query('ROLLBACK');
 await transaction(client,()=>client.query(modules.at(-1)));for(const table of tables)assert.equal(await value(client,"SELECT has_table_privilege('crest_web',$1,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE') AS value",['crest.'+table]),false);
 await assert.rejects(web.query('SELECT * FROM crest.jobs'),e=>e.code==='42501');await assert.rejects(client.query('DELETE FROM crest.jobs'),e=>e.code==='42501'&&e.message==='CREST_BOOKING_COMMAND_REQUIRED');
 await transaction(client,()=>client.query(cancellation));
 await transaction(client,()=>client.query(reschedule));
 await transaction(client,()=>client.query(scheduleCommands));
 await transaction(client,()=>client.query(historyReads));
 await transaction(client,()=>client.query(originalResolution));
 await transaction(client,()=>client.query(typedOriginalSql));
 await transaction(client,()=>client.query(contextSql));
});
test('accepted paid and complimentary scope commits one real retained job, reservation, history and exact audit',async()=>{
 const f=await fixture(),q=request(f),result=await book(f,q);assert.equal(result.state,'committed');assert.equal(result.receipt.jobId,q.job);assert.equal(result.receipt.version,'1');
 const job=(await client.query('SELECT state,current_appointment_id FROM crest.jobs WHERE business_id=$1 AND id=$2',[f.business,q.job])).rows[0];assert.equal(job.state,'scheduled');assert.equal(job.current_appointment_id,result.receipt.appointmentId);
 assert.equal(await value(client,'SELECT count(*)::int AS value FROM crest.current_scope_allocation_parts WHERE business_id=$1 AND job_id=$2 AND allocation_state=\'assigned\'',[f.business,q.job]),2);
 assert.equal(await value(client,'SELECT sum(amount_cents)::text AS value FROM crest.current_scope_allocation_parts WHERE business_id=$1 AND job_id=$2',[f.business,q.job]),'25000');
 assert.equal(await value(client,'SELECT count(*)::int AS value FROM crest.scope_allocations WHERE business_id=$1 AND job_id IS NULL AND allocation_state=\'unassigned\'',[f.business]),2);
 const actual=await counts(f.business);for(const table of ['jobs','job_vehicles','job_encounters','appointments','operator_controls','schedule_reservations','job_events'])assert.equal(actual['crest.'+table],1);assert.equal(actual['crest.allocation_plan_versions'],2);assert.equal(actual['crest.allocation_plan_parts'],2);
 assert.equal(await value(client,"SELECT to_char(start_at AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"') AS value FROM crest.appointments WHERE business_id=$1",[f.business]),q.body.appointment.start_at);
 booked={f,q,result};
});
test('original lookup and identical replay return the retained receipt without new rows; changed reuse conflicts',async()=>{
 const {f,q,result}=booked,before=await counts(f.business);assert.deepEqual(await lookup(f,q.operation),result);assert.deepEqual(await book(f,q),result);const changed=structuredClone(q);changed.body.workLocation.locationText+=' changed';assert.deepEqual(await book(f,changed),{state:'conflict',reason:'operation'});assert.deepEqual(await counts(f.business),before);assert.deepEqual(await lookup(f,randomUUID()),{state:'absent'});
});
