function splitRequest(f){
 const first=request(f),paid=first.body.allocationPlans.find(p=>p.parts[0].amountCents!=='0'),base=paid.parts[0];
 paid.parts=[{...base,grossInclusiveCents:'12500',amountCents:'12500',scopeDescription:'First explicit half of accepted synthetic scope'}, {...base,partitionId:randomUUID(),jobId:null,state:'unassigned',grossInclusiveCents:'12500',amountCents:'12500',scopeDescription:'Remaining explicit half of accepted synthetic scope'}];
 const second=request(f,{mode:'1'});second.body.allocationPlans=[{...structuredClone(paid),expectedSequence:'1',reason:'Allocate the retained remaining scope to a second visit',parts:paid.parts.map((part,index)=>({...part,...index===1?{jobId:second.job,state:'assigned'}:{}}))}];
 return {first,second};
}
function move(q,start,end){Object.assign(q.body.appointment,{start_at:start+'Z',end_at:end+'Z',local_start:start,local_end:end});}
test('split visits preserve prior assigned and zero-dollar identity; conflicting second visit needs exact review and a reason',async()=>{
 const f=await fixture(),{first,second}=splitRequest(f),original=await book(f,first);assert.equal(original.state,'committed');move(second,'2026-11-03T10:30:00.123456','2026-11-03T11:30:00.123456');
 const before=await counts(f.business);assert.deepEqual(await book(f,second),{state:'conflict',reason:'review'});assert.deepEqual(await counts(f.business),before);
 second.body.conflictReview.expectedAppointmentIds=[original.receipt.appointmentId];assert.deepEqual(await book(f,second),{state:'conflict',reason:'review'});assert.deepEqual(await counts(f.business),before);
 second.body.conflictReview.overrideReason='Owner explicitly reviewed the actual synthetic overlap and will arrange separate operator coverage before real use';const next=await book(f,second);assert.equal(next.state,'committed');
 assert.equal(await value(client,'SELECT count(*)::int AS value FROM crest.schedule_override_conflicts WHERE business_id=$1 AND conflicting_appointment_id=$2',[f.business,original.receipt.appointmentId]),1);
 const parts=(await client.query('SELECT stable_partition_id,job_id,amount_cents::text,allocation_state FROM crest.current_scope_allocation_parts WHERE business_id=$1',[f.business])).rows;assert.equal(parts.length,3);assert(parts.some(p=>p.job_id===first.job&&p.amount_cents==='12500'));assert(parts.some(p=>p.job_id===second.job&&p.amount_cents==='12500'));
 const complimentary=f.sources.find(s=>s.amount_cents==='0');assert(parts.some(p=>p.stable_partition_id===complimentary.stable_partition_id&&p.job_id===first.job&&p.amount_cents==='0'));
 const page1=await list(f,{size:1});assert.equal(page1.jobs.length,1);assert.equal(page1.hasMore,true);assert.equal(page1.jobs[0].jobId,first.job);const page2=await list(f,{size:1,afterStart:page1.jobs[0].startAt,afterJob:page1.jobs[0].jobId});assert.equal(page2.jobs[0].jobId,second.job);assert.equal(page2.hasMore,false);
 assert.deepEqual(await lookup(f,first.operation),original);assert.deepEqual(await book(f,first),original);
 const stolen=request(f,{mode:'1'});stolen.body.allocationPlans=structuredClone(second.body.allocationPlans);stolen.body.allocationPlans[0].expectedSequence='2';for(const p of stolen.body.allocationPlans[0].parts)p.jobId=stolen.job;move(stolen,'2026-11-04T10:00:00.123456','2026-11-04T11:00:00.123456');const safe=await counts(f.business);await assert.rejects(book(f,stolen),e=>e.code==='23514'&&e.message==='CREST_BOOKING_ASSIGNED_SCOPE_RETAINED');assert.deepEqual(await counts(f.business),safe);
});
